// Host test of REWINDBOX_ISO_IMAGE_LIFETIME_621 against the real
// rpcs3/Loader/ISO.cpp (compiled with test/rpcs3_core621/iso_stub, POSIX I/O).
// Usage: iso_lifetime_test <expect: fixed|defect> <image A> <image B> <workdir>
// Images are generated by test/rpcs3_core621_test.py: A holds PS3_DISC.SFB and
// PS3_GAME/{PARAM.SFO, ICON0.PNG, USRDIR/DATA.BIN}, B the same names with
// other bytes. Expected file contents are deterministic (see expected()).
#include "stdafx.h"
#include "Loader/ISO.h"

#include <sys/stat.h>
#include <unistd.h>

#include <atomic>
#include <cstdio>
#include <filesystem>
#include <random>
#include <thread>

static int g_failures = 0;
#define CHECK(cond) do { if (!(cond)) { std::fprintf(stderr, "FAIL %s:%d %s\n", __FILE__, __LINE__, #cond); ++g_failures; } } while (0)

namespace
{
// Byte i of a file: same formula as the generator (seed per image and file).
u8 expected_byte(u8 seed, u64 index) { return static_cast<u8>((index * 131 + seed * 7 + (index >> 11)) & 0xff); }

std::string device_path(const char* name) { return iso_device::virtual_device_name + "/" + name; }

// Opens through the device as the guest does (sys_fs -> device->open).
std::unique_ptr<fs::file_base> open(iso_device& device, const char* name)
{
	return device.open(device_path(name), fs::read);
}

// Reads the whole file and compares it with the generator's bytes.
// Returns "ok", "mismatch" or the exception text.
std::string verify(fs::file_base& file, u8 seed, u64 size)
{
	try
	{
		std::vector<u8> data(size);
		u64 done = 0;
		while (done < size)
		{
			const u64 got = file.read_at(done, data.data() + done, size - done);
			if (!got) return "short";
			done += got;
		}
		for (u64 i = 0; i < size; ++i)
			if (data[i] != expected_byte(seed, i)) return "mismatch";
		return "ok";
	}
	catch (const std::exception& error)
	{
		return error.what();
	}
}

u64 data_size() { return 3 * 2048 * 37 + 1234; } // USRDIR/DATA.BIN, several extents' worth of sectors

int image_descriptors(const std::string& path_now)
{
	struct stat target{};
	if (::stat(path_now.c_str(), &target) != 0) return -1;
	int count = 0;
	// /dev/fd lists this process's descriptors on Linux and Darwin.
	for (const auto& entry : std::filesystem::directory_iterator("/dev/fd"))
	{
		struct stat info{};
		if (::stat(entry.path().c_str(), &info) == 0 && info.st_ino == target.st_ino && info.st_dev == target.st_dev) ++count;
	}
	return count;
}
}

int main(int argc, char** argv)
{
	if (argc != 5) return 2;
	const std::string expect = argv[1];
	const std::string image_a = argv[2], image_b = argv[3], work = argv[4];
	const bool fixed = expect == "fixed";

	// 1. Mount A and read one file: the baseline works for both builds.
	auto device = std::make_shared<iso_device>(image_a);
	CHECK(open(*device, "PS3_GAME/PARAM.SFO") != nullptr);
	auto early = open(*device, "PS3_GAME/ICON0.PNG");
	CHECK(early && verify(*early, 0x21, 4096) == "ok");

	// 2. The mounted image is renamed during the session (the private copy
	// DiscImages/<ID>/disc.iso moved away), then the game opens a disc file it
	// never opened before.
	const std::string renamed = work + "/moved-disc.iso";
	CHECK(std::rename(image_a.c_str(), renamed.c_str()) == 0);
	auto late = open(*device, "PS3_GAME/USRDIR/DATA.BIN");
	std::string late_result = late ? verify(*late, 0x5a, data_size()) : "open_refused";
	std::printf("rename_then_new_file=%s\n", late_result.c_str());
	if (!fixed)
	{
		// Core 619: the open "succeeds" and the first read throws (the Minecraft report).
		CHECK(late != nullptr);
		CHECK(late_result == "Null object.");
		std::printf("defect reproduced: a file first opened after the rename fails on its first read\n");
		return g_failures ? 1 : 0;
	}
	CHECK(late_result == "ok");
	CHECK(early && verify(*early, 0x21, 4096) == "ok"); // a file opened before the rename too

	// 3. A different image is copied to the old path: the mounted disc keeps
	// reading the image it parsed (same inode, same directory tree).
	std::filesystem::copy_file(image_b, image_a);
	auto after_replace = open(*device, "PS3_GAME/ICON0.PNG");
	CHECK(after_replace && verify(*after_replace, 0x21, 4096) == "ok");

	// 4. Concurrent reads of several files from 8 threads, random offsets.
	std::atomic<int> bad{0};
	std::vector<std::thread> threads;
	for (int t = 0; t < 8; ++t)
	{
		threads.emplace_back([&, t] {
			std::mt19937 random(t);
			auto file = open(*device, t % 2 ? "PS3_GAME/USRDIR/DATA.BIN" : "PS3_GAME/ICON0.PNG");
			const u64 size = t % 2 ? data_size() : 4096;
			const u8 seed = t % 2 ? 0x5a : 0x21;
			if (!file) { bad++; return; }
			std::vector<u8> buffer(3000);
			for (int i = 0; i < 4000; ++i)
			{
				const u64 offset = random() % size;
				const u64 length = std::min<u64>(1 + random() % buffer.size(), size - offset);
				u64 done = 0;
				while (done < length)
				{
					const u64 got = file->read_at(offset + done, buffer.data() + done, length - done);
					if (!got) { bad++; return; }
					done += got;
				}
				for (u64 j = 0; j < length; ++j)
					if (buffer[j] != expected_byte(seed, offset + j)) { bad++; return; }
			}
		});
	}
	for (auto& thread : threads) thread.join();
	CHECK(bad.load() == 0);

	// 5. Stop: the device goes away (unload_iso) while a file is still open; it
	// keeps reading, and closing the last file releases the image descriptor.
	CHECK(image_descriptors(renamed) == 1);
	auto survivor = open(*device, "PS3_GAME/USRDIR/DATA.BIN");
	late.reset();
	early.reset();
	after_replace.reset();
	fs::set_virtual_device("iso_overlay_fs_dev", device);
	device.reset();
	unload_iso();
	CHECK(fs::virtual_devices().empty());
	CHECK(survivor && verify(*survivor, 0x5a, data_size()) == "ok");
	CHECK(image_descriptors(renamed) == 1);
	survivor.reset();
	CHECK(image_descriptors(renamed) == 0);
	CHECK(fs::open_descriptors().load() == 0);

	// 6. Another disc is mounted (B, now also at the old path of A).
	auto second = std::make_shared<iso_device>(image_b);
	auto other = open(*second, "PS3_GAME/USRDIR/DATA.BIN");
	CHECK(other && verify(*other, 0x77, data_size()) == "ok");
	other.reset();
	second.reset();
	CHECK(fs::open_descriptors().load() == 0);

	// 7. An image that cannot be parsed or opened: every open is refused (noent)
	// instead of handing out a file whose first read throws.
	iso_device missing(work + "/does-not-exist.iso");
	fs::g_tls_error = fs::error::ok;
	CHECK(open(missing, "PS3_GAME/PARAM.SFO") == nullptr);
	CHECK(fs::g_tls_error == fs::error::noent);

	if (g_failures)
	{
		std::fprintf(stderr, "%d failure(s)\n", g_failures);
		return 1;
	}
	std::printf("iso lifetime: all checks passed\n");
	return 0;
}
